interface ContentItem {
  id: number;
  title: string;
  url?: string;
  description?: string;
  excerpt?: string;
  date?: string;
  thumbnail?: string;
}

interface Props {
  title: string;
  content: ContentItem[];
  type: 'links' | 'videos' | 'blog';
}

const ContentSection: React.FC<Props> = ({ title, content, type }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    url: '',
    description: '',
    excerpt: '',
    date: new Date().toISOString().split('T')[0]
  });

  const openModal = () => setIsModalOpen(true);
  const closeModal = () => {
    setIsModalOpen(false);
    setFormData({
      title: '',
      url: '',
      description: '',
      excerpt: '',
      date: new Date().toISOString().split('T')[0]
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Here you would normally send the data to your backend
    console.log('New content:', formData);
    closeModal();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  return (
    <SectionContainer id={type === 'links' ? 'resources' : type === 'videos' ? 'videos' : 'blog'}>
      <SectionTitle
        initial={{ opacity: 0, y: -50 }}
        whileInView={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        {title}
      </SectionTitle>

      <ContentGrid>
        {content.map((item, index) => (
          <ContentCard
            key={item.id}
            initial={{ opacity: 0, y: 50 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: index * 0.1 }}
            whileHover={{ scale: 1.02 }}
          >
            {type === 'videos' && (
              <VideoThumbnail />
            )}

            {type === 'blog' && (
              <BlogMeta>
                <BlogDate>{item.date}</BlogDate>
              </BlogMeta>
            )}

            <CardTitle>{item.title}</CardTitle>

            {type === 'links' && (
              <>
                <CardDescription>{item.description}</CardDescription>
                <CardLink href={item.url} target="_blank" rel="noopener noreferrer">
                  Visit Link →
                </CardLink>
              </>
            )}

            {type === 'videos' && (
              <>
                <CardDescription>{item.description}</CardDescription>
                <CardLink href={item.url} target="_blank" rel="noopener noreferrer">
                  Watch Video →
                </CardLink>
              </>
            )}

            {type === 'blog' && (
              <>
                <CardDescription>{item.excerpt}</CardDescription>
                <ReadMoreLink
                  href={item.url}
                  whileHover={{ x: 5 }}
                >
                  Read More →
                </ReadMoreLink>
              </>
            )}
          </ContentCard>
        ))}
      </ContentGrid>

      <AddContentButton
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        onClick={openModal}
      >
        Add {type === 'links' ? 'Link' : type === 'videos' ? 'Video' : 'Blog Post'}
      </AddContentButton>

      <Modal
        isOpen={isModalOpen}
        initial={{ opacity: 0 }}
        animate={{ opacity: isModalOpen ? 1 : 0 }}
        onClick={closeModal}
      >
        <ModalContent
          initial={{ scale: 0.8 }}
          animate={{ scale: 1 }}
          onClick={(e) => e.stopPropagation()}
        >
          <ModalTitle>
            Add New {type === 'links' ? 'Link' : type === 'videos' ? 'Video' : 'Blog Post'}
          </ModalTitle>

          <form onSubmit={handleSubmit}>
            <FormGroup>
              <Label htmlFor="title">Title</Label>
              <Input
                type="text"
                id="title"
                name="title"
                value={formData.title}
                onChange={handleInputChange}
                required
              />
            </FormGroup>

            {(type === 'links' || type === 'videos') && (
              <FormGroup>
                <Label htmlFor="url">URL</Label>
                <Input
                  type="url"
                  id="url"
                  name="url"
                  value={formData.url}
                  onChange={handleInputChange}
                  required
                />
              </FormGroup>
            )}

            {type === 'blog' && (
              <FormGroup>
                <Label htmlFor="date">Date</Label>
                <Input
                  type="date"
                  id="date"
                  name="date"
                  value={formData.date}
                  onChange={handleInputChange}
                />
              </FormGroup>
            )}

            <FormGroup>
              <Label htmlFor="description">
                {type === 'blog' ? 'Excerpt' : 'Description'}
              </Label>
              <TextArea
                id={type === 'blog' ? 'excerpt' : 'description'}
                name={type === 'blog' ? 'excerpt' : 'description'}
                value={type === 'blog' ? formData.excerpt : formData.description}
                onChange={handleInputChange}
                required
              />
            </FormGroup>

            <ButtonGroup>
              <SubmitButton
                type="submit"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                Submit
              </SubmitButton>
              <CancelButton
                type="button"
                onClick={closeModal}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                Cancel
              </CancelButton>
            </ButtonGroup>
          </form>
        </ModalContent>
      </Modal>
    </SectionContainer>
  );
};

export default ContentSection;
